<?php
namespace Junior; use Junior\Clientside\Request, Junior\Clientside\Response, Junior\Clientside\Exception; class Client { public $uri, $authHeader; public function __construct($uri) { $this->uri = $uri; } public function __call($method, $params) { $req = new Request($method, $params); return $this->sendRequest($req); } public function setBasicAuth($username, $password) { $this->authHeader = "Authorization: Basic " . base64_encode("$username:$password") . "\r\n"; } public function clearAuth() { $this->authHeader = null; } public function sendRequest($req) { $response = $this->send($req->getJSON()); if ($response->id != $req->id) { throw new Clientside\Exception("Mismatched request id"); } return $response; } public function sendNotify($req) { if (property_exists($req, 'id') && $req->id != null) { throw new Clientside\Exception("Notify requests must not have ID set"); } $this->send($req->getJSON(), true); return true; } public function sendBatch($reqs) { $arr = array(); $ids = array(); $all_notify = true; foreach ($reqs as $req) { if ($req->id) { $all_notify = false; $ids[] = $req->id; } $arr[] = $req->getArray(); } $response = $this->send(json_encode($arr, JSON_UNESCAPED_UNICODE), $all_notify); if ($all_notify) { return true; } $ordered_response = array(); foreach ($ids as $id) { if (array_key_exists($id, $response)) { $ordered_response[] = $response[$id]; unset($response[$id]); } else { throw new Clientside\Exception("Missing id in response"); } } if (count($response) > 0) { throw new Clientside\Exception("Extra id(s) in response"); } return $ordered_response; } public function send($json, $notify = false) { $header = "Content-Type: application/json\r\n"; if ($this->authHeader) { $header .= $this->authHeader; } $opts = array( 'http' => array( 'method' => 'POST', 'header' => $header, 'content' => $json)); $context = stream_context_create($opts); try { $response = file_get_contents($this->uri, false, $context); } catch (\Exception $e) { $message = "Unable to connect to {$this->uri}"; $message .= PHP_EOL . $e->getMessage(); throw new Clientside\Exception($message); } if ($response === false) { throw new Clientside\Exception("Unable to connect to {$this->uri}"); } if ($notify) { return true; } $json_response = $this->decodeJSON($response); return $this->handleResponse($json_response); } function decodeJSON($json) { $json_response = safe_json_decode($json); if ($json_response === null) { throw new Clientside\Exception("Unable to decode JSON response from: {$json}"); } return $json_response; } public function handleResponse($response) { if (is_array($response)) { $response_arr = array(); foreach ($response as $res) { $response_arr[$res->id] = $this->handleResponse($res); } return $response_arr; } return $response; } } 